if (step === 'dogfood') {
  phase('Dogfood')
  const to = (args && args.to) || DOGFOOD.length
  const results = []
  for (const t of DOGFOOD.slice(from, to)) {
    const r = await workflow({ scriptPath: IMPL }, { ...t, model: t.model || 'sonnet', effort: t.effort || 'medium' })
    results.push(r)
    if (!r || r.status !== 'merged') { log(`Stopped at ${t.id}`); return { results, stopped_at: t.id } }
  }
  return { results }
}

if (step === 'material') {
  phase('Material')
  const results = []
  for (const t of MATERIAL.slice(from)) {
    const r = await workflow({ scriptPath: IMPL }, { ...t, model: t.model || 'sonnet', effort: t.effort || 'medium' })
    results.push(r)
    if (!r || r.status !== 'merged') { log(`Stopped at ${t.id}`); return { results, stopped_at: t.id } }
  }
  return { results }
}

log(`unknown step '${step}'; this script has five: material, v020, polish, names, dogfood`)
return { results: [], stopped_at: null }
